INSERT INTO dictation_question_progress (learner, subject_id, direction, level, source, current_question_id, answered, asked_ids, asked_count, right_count, round_start) VALUES (:learner, CAST(:subject_id AS INTEGER), :direction, :level, :source, 0, 1, '', 0, 0, (SELECT COALESCE(MAX(id), 0) FROM dictation_question_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER))) ON CONFLICT(learner, subject_id) DO UPDATE SET direction = excluded.direction, level = excluded.level, source = excluded.source WHERE dictation_question_progress.current_question_id = 0
